import{_ as e,c as p,o as r,ah as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"3、【屯】 震下坎上","description":"周易尚氏学 - 3、【屯】 震下坎上","frontmatter":{"title":"3、【屯】 震下坎上","description":"周易尚氏学 - 3、【屯】 震下坎上"},"headers":[],"relativePath":"zh/classics/shangshi/008.md","filePath":"zh/classics/shangshi/008.md"}'),h={name:"zh/classics/shangshi/008.md"};function s(t,a,l,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_3、【屯】-震下坎上" tabindex="-1">3、【屯】 震下坎上 <a class="header-anchor" href="#_3、【屯】-震下坎上" aria-label="Permalink to “3、【屯】 震下坎上”">​</a></h1><p>上坎为险。下震为动。动乎险中。故名曰屯。屯难也。止也。诸家皆以乾通坤为元亨。三之正成既济为利贞。按以乾通坤为元亨。初五得位。乾元以通是也。以三之正成既济。为利贞非也。利贞者利于贞定也。勿用有攸往。申其义也。端木国瑚谓遇春夏卦。即曰元亨。秋冬卦即曰利贞。易本以时为主。说颇胜于旧解。屯由震春以至坎冬。一年气备。故曰元亨又曰利贞。乾初勿用。往遇险。故曰勿用有攸往。侯君也。主也。震为君。初临万民。五居尊位。故曰利建侯。</p><p>彖曰。屯。刚柔始交而难生。动乎险中。大亨贞。雷雨之动满盈。天造草昧。宜建侯而不宁。</p><p>始交为初五也。前乾坤二卦。皆纯阳纯阴莫能交。屯下震以乾交坤初。上坎以乾交坤中。以其次纯乾纯坤之后。刚柔杂始见。故曰始交。难谓坎也。蹇传云蹇难也。即指上坎。动而遇险。故曰难生。下雷上雨。坤为多故曰满盈。造始也。草杂乱。昧冥昧。坤为茅茹为乱。故曰草。地黑故曰昧。易林艮之晋云。釜甑草土。即以晋下坤为草。为釜。天造草昧者。言天地之运。始于草昧。故宜建侯于此时。使万物有主也。诸家皆用虞翻说。谓刚柔始交。为坎二交初。如是穿凿。又何不可谓革四交初。盖虞氏不知始字承前两卦乾坤而言。而以为指屯初二。故误解若是。后阅道光间。卞斌周易通解。亦谓始交指初五。然则此义百年前已发之。</p><p>象曰。云雷。屯。君子以经纶。</p><p>经纶据释文。王弼本作经论。今本作经纶者。乃孔本也。因将王注亦改之矣。释文又云。黄颖曰经纶匡济也。本亦作伦。案释名云。纶伦也。为之有伦理也。论语正义引郑玄云。论者。纶也。理也。然则纶论论。字微异。义则同也。若以卦象言。震为言。初至五正反震。似论于易象较切。若正义所云刘表郑玄作沦。似不合矣。</p><p>初九。盘桓。利居贞。利建侯。</p><p>盘桓。释文云族也。尔雅释水钩盘。郭注水曲如钩。流盘桓不直前也。禹贡西倾因桓是来。注。桓陇皈名。其道盘旋。曲而上旋。即不能直前也。盘盘通。释文云。本亦作盘。马又作盘。又或作般。皆以音同通用。外坎故利居贞不动。震为主。建侯则坤民有主。故利。</p><h3 id="象曰。虽盘桓。志行正也。以贵下贱。大得民也。" tabindex="-1">象曰。虽盘桓。志行正也。以贵下贱。大得民也。 <a class="header-anchor" href="#象曰。虽盘桓。志行正也。以贵下贱。大得民也。" aria-label="Permalink to “象曰。虽盘桓。志行正也。以贵下贱。大得民也。”">​</a></h3><p>坤为民。阴贱阳贵。阳在下。故曰以贵下贱。阳为大。初阳临群阴。故曰大得民。</p><p>六二。屯如邅。乘马班如。匪寇婚媾。女子贞不字。十年乃字。</p><p>阴遇阴得敌。故屯邅不进。释文云。邅。马行不进之貌。班。子夏传相牵不进儿。郑作般。般盘同。亦盘桓不进也。又震为马。坤坎皆为马。马多故曰班如。言行列不前也。吴先生曰。汉书车班班。往河间。义同此也。五坎为寇。二与五应。故曰匪寇。曰婚媾。乃二前为三四所阻。下为初阳所牵。体又为坤。坤虚故不字。字妊育也。震为孕。左传昭元年。武王邑姜方震太叔是也。故震为妊育。王引之力辟宋耿南仲朱子以字为许嫁之非。其说是也。今河北尚呼牝牛为字牛。义本此也。坤为年。数十。故曰十年乃字。言二五。应与虽难。然究为正应。久必合也。</p><h3 id="象曰。六二之难。乘刚也。十年乃字。反常也。" tabindex="-1">象曰。六二之难。乘刚也。十年乃字。反常也。 <a class="header-anchor" href="#象曰。六二之难。乘刚也。十年乃字。反常也。" aria-label="Permalink to “象曰。六二之难。乘刚也。十年乃字。反常也。”">​</a></h3><p>此难字与象传难生难字不同。彼指坎。此谓乘刚字难也。说者多混而同之。非。乘刚势逆。故字难。</p><p>六三。即鹿无虞。惟入于林中。君子几。不如合。往吝。</p><p>鹿。虞翻王肃皆作麓。鹿麓古通。诗瞻彼旱鹿。周语作旱鹿。韦注鹿山足也。三为艮初。正山足也。即鹿者。言至山足而从禽也。即就也。虞备虞也。孟子曰。有不虞之誉。义同此也。言田猎而无备虞。焉能有禽。震为木。艮亦为木。故曰林中。坤虚故空人林中。几者事之先见者也。舍去也。言君子见几而去也。上无应故往吝。艮为君子。淮南子说此云。夫施薄而望厚者。未之有也。又三国志陈琳传。易称即鹿无虞。夫微物尚不可欺。夫所谓欺。即无备虞也。王弼云。虽见其禽而无其虞。徒人于林中。亦诂虞为备虞。乃孔疏忽谓虞为虞官。失王义矣。左传隐五年。不备不虞。不可以师。正与此无虞义同。</p><h3 id="象曰。即鹿无虞。以从禽也。君子舍之。往吝。穷也。" tabindex="-1">象曰。即鹿无虞。以从禽也。君子舍之。往吝。穷也。 <a class="header-anchor" href="#象曰。即鹿无虞。以从禽也。君子舍之。往吝。穷也。" aria-label="Permalink to “象曰。即鹿无虞。以从禽也。君子舍之。往吝。穷也。”">​</a></h3><p>从禽义与即鹿同。吝遴古通。说文行难也。三无应得敌故行难。吝字初见。说文口部引作吝。云恨惜也。◇部引又作遴。云行难。愚以为凡言往吝者。宜从行难义。祇言吝者。宜从恨惜义。此曰往吝。即行难也。</p><p>六四。乘马班如。求婚媾。往吉。无不利。</p><p>坎坤皆为马。故亦曰班如。艮为求。四与初本为正应。婚媾而已。然必求者。以二三为阻也。知其阻而求之。故往吉也。四上承阳。下有应。故曰无不利。</p><h3 id="象曰。求而往。明也。" tabindex="-1">象曰。求而往。明也。 <a class="header-anchor" href="#象曰。求而往。明也。" aria-label="Permalink to “象曰。求而往。明也。”">​</a></h3><p>艮火故曰明。艮阳在上亦明。自艮火艮明象失传。诸家皆以三变互离为明矣。岂知旅九三云。焚其次。易林大壮之遁云。火烂销金。皆以艮为火。说详焦氏易诂中。</p><p>九五。屯其膏。小贞吉。大贞凶。</p><p>坎水故曰膏，坎陷故屯其膏。盖五虽下履重阴。然坤民三分之二。为初所有。四又应初。五虽君位。实无一民。故膏泽无所施也。小谓二。五应二。阴得阳应故吉。大谓五。五虚拥尊位。威柄下移。孤露无辅。故大贞凶。震为威。坤为柄。贞卜问也。诸家强以贞正说之。夫正而有大小。已不词矣。大正而凶。益悖理矣。惠士奇知其不安。又以固为说。其不协与正无异也。</p><h3 id="象曰。屯其膏。施未光也。" tabindex="-1">象曰。屯其膏。施未光也。 <a class="header-anchor" href="#象曰。屯其膏。施未光也。" aria-label="Permalink to “象曰。屯其膏。施未光也。”">​</a></h3><p>坎为隐伏。故曰未光。</p><p>上六。乘马班如。泣血涟如。</p><p>坎为血。坎水故曰涟如。诗卫风。泣涕涟涟。释文。泣貌。坎忧惧。下无应。故有是象。</p><h3 id="象曰。泣血涟如。何可长也。" tabindex="-1">象曰。泣血涟如。何可长也。 <a class="header-anchor" href="#象曰。泣血涟如。何可长也。" aria-label="Permalink to “象曰。泣血涟如。何可长也。”">​</a></h3><p>上六居卦之极。故曰不长。</p>',30)])])}const m=e(h,[["render",s]]);export{_ as __pageData,m as default};
